create or replace function public.start_attempt(p_full_name text,p_agency text) returns uuid language plpgsql security definer set search_path=public as $$declare c uuid;a uuid;begin if auth.uid() is null then raise exception 'Authentication required';end if;if trim(p_full_name)='' or trim(p_agency)='' then raise exception 'Name and agency required';end if;insert into candidates(full_name,agency) values(trim(p_full_name),trim(p_agency)) on conflict(full_name,agency) do update set full_name=excluded.full_name returning id into c;select id into a from attempts where user_id=auth.uid() and candidate_id=c and status='in_progress' and now()<expires_at order by started_at desc limit 1;if a is null then insert into attempts(candidate_id,user_id) values(c,auth.uid()) returning id into a;insert into answers(attempt_id,question_id) select a,id from questions on conflict do nothing;end if;return a;end$$;
create or replace function public.submit_attempt(p_attempt_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare a attempts%rowtype;total numeric(4,1);begin select * into a from attempts where id=p_attempt_id and user_id=auth.uid() for update;if not found then raise exception 'Attempt not found';end if;if a.status<>'in_progress' then return public.get_attempt_result(p_attempt_id);end if;update answers x set is_correct=case when jsonb_array_length(x.selected)=0 then false when q.type='single' then x.selected<@q.correct and x.selected@>q.correct when not(x.selected<@q.correct) then false else x.selected@>q.correct end,is_partial=q.type='multiple' and jsonb_array_length(x.selected)>0 and x.selected<@q.correct and not(x.selected@>q.correct),points=case when jsonb_array_length(x.selected)=0 then 0 when q.type='single' and x.selected<@q.correct and x.selected@>q.correct then q.points when q.type='multiple' and x.selected<@q.correct and x.selected@>q.correct then q.points when q.type='multiple' and x.selected<@q.correct then q.points/2 else 0 end from questions q where x.attempt_id=a.id and q.id=x.question_id;select coalesce(sum(points),0) into total from answers where attempt_id=a.id;update attempts set status='submitted',submitted_at=now(),duration_sec=least(extract(epoch from(now()-started_at))::int,1800),score=total,passed=total>=14,level=case when total>=16 then'acquis' when total>=14 then'acquis_reserves' when total>=10 then'en_cours' else'non_acquis'end where id=a.id;return public.get_attempt_result(a.id);end$$;
create or replace function public.get_attempt_result(p_attempt_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare out jsonb;begin if not exists(select 1 from attempts where id=p_attempt_id and status='submitted' and(user_id=auth.uid() or is_admin())) then raise exception 'Result unavailable';end if;select jsonb_build_object('attempt',to_jsonb(a),'candidate',to_jsonb(c),'answers',coalesce(jsonb_agg(jsonb_build_object('question_id',q.id,'section',q.section,'type',q.type,'text',q.text,'options',q.options,'selected',x.selected,'correct',q.correct,'explanation',q.explanation,'is_correct',x.is_correct,'is_partial',x.is_partial,'points',x.points) order by q.id),'[]')) into out from attempts a join candidates c on c.id=a.candidate_id join answers x on x.attempt_id=a.id join questions q on q.id=x.question_id where a.id=p_attempt_id group by a.id,c.id;return out;end$$;
create or replace function public.expire_stale_attempts() returns integer language plpgsql security definer set search_path=public as $$declare n int;begin update attempts set status='expired' where status='in_progress' and expires_at<=now();get diagnostics n=row_count;return n;end$$;
revoke all on function public.start_attempt(text,text),public.submit_attempt(uuid),public.get_attempt_result(uuid) from public;grant execute on function public.start_attempt(text,text),public.submit_attempt(uuid),public.get_attempt_result(uuid) to authenticated;
